import {config} from './config.js';
import {cents,remaining,status,totals,payment,canApprove,csvCell,localDate} from './core.mjs';
import {profileFromUser} from './profile.mjs';

const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,currency='INR')=>new Intl.NumberFormat('en-IN',{style:'currency',currency:currency||'INR',maximumFractionDigits:n%100?2:0}).format(n/100);
const day=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not provided';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',invoice:'M7 3h8l4 4v14H5V3h2 M14 3v5h5 M8 12h8 M8 16h6',chat:'M21 11a8 8 0 0 1-8 8H5l-4 3V11a8 8 0 0 1 8-8h4a8 8 0 0 1 8 8Z M6 10h10 M6 14h6',wallet:'M3 6h18v14H3z M3 6l15-3v3 M16 12h5v4h-5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 5v14 M5 12h14',search:'M17 17l5 5 M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'M4 12l5 5L20 6',close:'M5 5l14 14 M5 19L19 5',logout:'M10 3H3v18h7 M8 12h13 M16 7l5 5-5 5',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',clock:'M12 7v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 11l3 3 5-5',menu:'M3 6h18 M3 12h18 M3 18h18',moon:'M21 13A9 9 0 1 1 11 3a7 7 0 0 0 10 10',edit:'M14 4l6 6 M4 16L17 3l4 4L8 20H4z',pause:'M8 4v16 M16 4v16'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.invoice}"/></svg>`;
const brand=()=>'<div class="brand"><img src="/favicon.svg" alt="" width="38" height="38">cetld</div>';
const button=(action,label,cls='',id='')=>`<button type="button" class="btn ${cls}" data-action="${action}" aria-label="${escape(action==='detail'?'View invoice':label.replace(/<[^>]*>/g,'').trim()||action)}" ${id?`data-id="${escape(id)}"`:''}>${label}</button>`;
const tag=s=>`<span class="tag ${escape(s.toLowerCase().replaceAll(' ','-'))}">${escape(s)}</span>`;
const state={user:null,profile:profileFromUser(null),workspace:null,settings:null,customers:[],demo:false,invoices:[],payments:[],page:'Overview',search:'',filter:'All',loading:false,error:'',authMode:'login',recovery:false,conversationId:null,pendingFile:null};
let db=null,authError='',toastTimer,loadEpoch=0;
const readPref=(k,fallback)=>{try{return localStorage.getItem(k)??fallback}catch{return fallback}};
const pref=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
const toMinor=value=>Math.round(Number(value||0)*100);
const invoiceFromRow=(row,customers)=>{const customer=customers.find(x=>x.id===row.customer_id)||{};const meta=row.metadata||{};return {...row,number:row.invoice_number,client:customer.company_name||customer.name||'Customer',email:customer.email||'',amount_minor:toMinor(row.total_amount),paid_minor:toMinor(row.amount_paid),invoice_date:row.issue_date,followup_state:meta.followup_state||(['paid','cancelled','void'].includes(row.status)?'cancelled':'draft'),reminder_text:meta.reminder_text||'',bookkeeping_sync_status:meta.bookkeeping_sync_status||'not_configured',debtor_phone:customer.phone||'',...meta};};
const paymentFromRow=row=>({...row,amount_minor:toMinor(row.amount)});
document.documentElement.classList.toggle('dark',readPref('cetld.theme','light')==='dark');
document.documentElement.classList.toggle('reduce-motion',readPref('cetld.motion','on')==='off');

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function showError(container,error){let el=container.querySelector('[data-error]');if(el){el.textContent=error.message||String(error);el.classList.remove('hidden')}}
function authPage(){
 const mode=state.authMode;const signup=mode==='signup',reset=mode==='reset',recovery=mode==='recovery';
 $('#app').innerHTML=`<main class="auth"><section class="auth-story">${brand()}<div class="orbit"></div><div class="auth-copy"><div class="eyebrow">Collections, considered.</div><h1>Good work.<br>Good relationships.<br><em>Settled invoices.</em></h1><p>A clearer view of what you’re owed, and a more thoughtful way to follow up.</p><div class="collection-demo"><div class="demo-label">An illustration of a settled invoice</div><div class="receipt"><div class="row between"><p>INV-1048</p>${tag('Paid')}</div><strong>₹84,600</strong><div class="receipt-line"><span>Arbor &amp; Finch</span><span>Balance ₹0</span></div></div><div class="receipt-badge">${icon('check')}<span>Payment recorded.<br><small>Follow-up cancelled.</small></span></div></div></div><footer class="auth-foot"><span>Built for better business.</span><span>01 / A clear beginning</span></footer></section><section class="auth-panel"><div class="auth-box"><div class="eyebrow muted">Your collections workspace</div><h2>${signup?'Make room for growth.':reset?'Let’s get you back in.':recovery?'A fresh start.':'Welcome back.'}</h2><p class="muted">${signup?'Create your account to start managing invoices.':reset?'We’ll email you a secure password reset link.':recovery?'Choose a new password for your Cetld account.':'Sign in to keep your receivables moving.'}</p>${!reset&&!recovery?button('google','Continue with Google','google wide'):''}<form class="auth-form" id="auth-form">${!recovery?'<label class="field">Email address<input name="email" type="email" autocomplete="email" placeholder="you@company.com" required maxlength="254"></label>':''}${!reset?`<label class="field">Password<input name="password" type="password" autocomplete="${signup||recovery?'new-password':'current-password'}" ${signup||recovery?'minlength="12"':''} placeholder="${signup||recovery?'At least 12 characters':'Your password'}" required maxlength="128"></label>`:''}${signup?'<p class="muted"><small>Your records are private to your account. Use a password you don’t use elsewhere.</small></p>':''}<div class="error hidden" data-error role="alert"></div><button class="btn primary wide" type="submit" ${!db?'disabled':''}>${signup?'Create account':reset?'Send reset link':recovery?'Update password':'Sign in'} ${icon('arrow')}</button>${mode==='login'?'<button class="text-link" data-action="auth-reset" type="button">Forgot your password?</button>':''}</form><div class="auth-links">${signup?'Already have an account?':reset||recovery?'Remember your password?':'New to Cetld?'}<button data-action="${mode==='login'?'auth-signup':'auth-login'}">${mode==='login'?'Create an account':'Sign in'}</button></div>${authError?`<p class="notice">${escape(authError)}</p>`:''}<div class="auth-bottom">${button('demo','Explore an interactive demo '+icon('arrow'),'ghost')}<p class="muted">Sample data. No account or messages sent.</p></div></div></section></main>`;
 $('#auth-form').addEventListener('submit',submitAuth);
}
async function submitAuth(e){e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type=submit]');const data=new FormData(form);submit.disabled=true;const original=submit.innerHTML;submit.textContent='Please wait…';form.querySelector('[data-error]').classList.add('hidden');
 try{if(!db)throw Error('Authentication is unavailable. Please try again.');let result;const redirectTo=location.origin+'/';
 if(state.authMode==='signup'){result=await db.auth.signUp({email:data.get('email'),password:data.get('password'),options:{emailRedirectTo:redirectTo}});if(result.error)throw result.error;if(!result.data.session){authError='Check your email to confirm your account, then sign in.';state.authMode='login';authPage();return}}
 else if(state.authMode==='reset'){result=await db.auth.resetPasswordForEmail(data.get('email'),{redirectTo});if(result.error)throw result.error;authError='If this address has an account, a reset link will arrive shortly.';state.authMode='login';authPage();return}
 else if(state.authMode==='recovery'){result=await db.auth.updateUser({password:data.get('password')});if(result.error)throw result.error;state.recovery=false;state.authMode='login';history.replaceState(null,'',location.pathname);toast('Password updated');await enterAccount(result.data.user);return}
 else{result=await db.auth.signInWithPassword({email:data.get('email'),password:data.get('password')});if(result.error)throw result.error}
 if(result.data?.session)await enterAccount(result.data.user);
 }catch(err){showError(form,err)}finally{submit.disabled=false;submit.innerHTML=original}
}
async function googleSignIn(){if(!db)throw Error('Authentication is unavailable.');const {error}=await db.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/'}});if(error)throw error}
async function ensureAccount(user){const fallback=profileFromUser(user);let {data:profile,error:profileError}=await db.from('profiles').select('*').eq('user_id',user.id).maybeSingle();if(profileError)throw profileError;if(!profile){const result=await db.from('profiles').upsert({user_id:user.id,full_name:fallback.fullName}).select().single();if(result.error)throw result.error;profile=result.data}let {data:workspaces,error:workspaceError}=await db.from('workspaces').select('*').order('created_at').limit(1);if(workspaceError)throw workspaceError;let workspace=workspaces?.[0];if(!workspace){const result=await db.rpc('create_workspace',{p_name:fallback.businessName||`${fallback.fullName}'s workspace`,p_slug:null});if(result.error)throw result.error;workspace=result.data}const {data:settings,error:settingsError}=await db.from('workspace_settings').select('*').eq('workspace_id',workspace.id).single();if(settingsError)throw settingsError;state.workspace=workspace;state.settings=settings;state.profile={...fallback,fullName:profile.full_name||fallback.fullName,businessName:settings.business_name||workspace.name,secondaryLabel:settings.business_name||workspace.name,initials:profileFromUser({email:user.email,user_metadata:{full_name:profile.full_name||fallback.fullName}}).initials};}
async function enterAccount(user){if(!user)return;state.demo=false;state.user=user;await ensureAccount(user);state.invoices=[];state.payments=[];state.page='Overview';state.error='';await loadData()}
async function allRows(table){const rows=[];for(let offset=0;;offset+=1000){const {data,error}=await db.from(table).select('*').order('created_at',{ascending:false}).order('id').range(offset,offset+999);if(error)throw error;rows.push(...data);if(data.length<1000)return rows}}
async function loadData(){if(state.demo){render();return}if(!state.user||!state.workspace)return;const epoch=++loadEpoch;state.loading=true;state.error='';render();try{const workspaceId=state.workspace.id;const [customers,invoices,payments]=await Promise.all([db.from('customers').select('*').eq('workspace_id',workspaceId).order('name'),db.from('invoices').select('*').eq('workspace_id',workspaceId).order('created_at',{ascending:false}),db.from('payments').select('*').eq('workspace_id',workspaceId).order('paid_at',{ascending:false})]);for(const result of [customers,invoices,payments])if(result.error)throw result.error;if(epoch!==loadEpoch)return;state.customers=customers.data||[];state.invoices=(invoices.data||[]).map(row=>invoiceFromRow(row,state.customers));state.payments=(payments.data||[]).map(paymentFromRow)}catch(err){if(epoch!==loadEpoch)return;state.error=err.message||'Could not load your invoices.'}finally{if(epoch===loadEpoch){state.loading=false;render()}}}
function demo(){++loadEpoch;state.demo=true;state.user={id:'demo',email:'demo@cetld.local',user_metadata:{full_name:'Vedang Sharma',business_name:'Cetld demo'}};state.profile=profileFromUser(state.user);state.loading=false;state.error='';state.page='Overview';state.search='';state.filter='All';const date=n=>{const d=new Date();d.setDate(d.getDate()+n);return localDate(d)};state.invoices=[['Arbor & Finch',8460000,0,0,'draft'],['Morrow Studio',12800000,3000000,-7,'approved'],['Northlane Foods',4625000,0,-12,'paused'],['Cove Logistics',7240000,7240000,-3,'cancelled'],['Studio Parallel',3950000,0,6,'draft']].map((x,i)=>({id:crypto.randomUUID(),owner_id:'demo',number:`INV-${1048-i}`,client:x[0],email:'accounts@example.com',amount_minor:x[1],paid_minor:x[2],due_date:date(x[3]),followup_state:x[4],notes:'Sample invoice for exploring the workspace.',reminder_text:'',created_at:new Date().toISOString(),updated_at:new Date().toISOString()}));state.payments=state.invoices.filter(x=>x.paid_minor).map(x=>({id:crypto.randomUUID(),invoice_id:x.id,amount_minor:x.paid_minor,reference:'Sample bank transfer',created_at:new Date().toISOString()}));render()}
const nav=[['Overview','grid'],['Invoices','invoice'],['Conversations','chat'],['Payments','wallet'],['Connections','link'],['Settings','settings']];
function render(){if(!state.user||state.recovery){authPage();return}const {fullName,initials,secondaryLabel}=state.profile;$('#app').innerHTML=`<div class="shell"><button class="nav-scrim" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar">${brand()}<div class="nav-label">Workspace</div><nav class="nav" aria-label="Main navigation">${nav.map(([name,i])=>`<button data-action="navigate" data-page="${name}" class="${state.page===name?'active':''}" ${state.page===name?'aria-current="page"':''}>${icon(i)}${name}${name==='Invoices'?`<small>${state.invoices.length}</small>`:''}</button>`).join('')}</nav><div class="setup-card"><span class="setup-progress"><i></i></span><div><strong>Workspace setup</strong><small>${state.invoices.length?'2 of 3 complete':'1 of 3 complete'}</small></div>${button('onboarding',icon('arrow'),'ghost square')}</div><div class="sidebar-bottom"><div class="nav-label">Private workspace</div><div class="nav"><button data-action="logout">${icon('logout')}${state.demo?'Exit demo':'Sign out'}</button></div><div class="workspace-badge" aria-label="${escape(`${fullName}, ${secondaryLabel}`)}"><span class="avatar" aria-hidden="true">${escape(initials)}</span><div><strong title="${escape(fullName)}">${escape(fullName)}</strong><small title="${escape(secondaryLabel)}">${escape(secondaryLabel)}</small></div></div></div></aside><main class="main">${state.demo?'<div class="demo-mode"><span>Demo workspace · Changes last until you leave or refresh.</span><button data-action="logout">Exit demo</button></div>':''}<header class="topbar"><div class="row"><button class="btn ghost square mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb"><span>Workspace</span><span>/</span><strong>${state.page}</strong></div></div><div class="row"><span class="sync"><i></i>${state.demo?'Sample data':state.loading?'Loading…':state.error?'Sync unavailable':'Live workspace'}</span>${button('theme',icon('moon'),'ghost square')}${button('refresh',icon('refresh'),'ghost square')}<span class="avatar" title="${escape(fullName)}" aria-label="${escape(fullName)}">${escape(initials)}</span></div></header><div class="content">${state.error?`<div class="error load-error" role="alert">Could not load your workspace: ${escape(state.error)} ${button('refresh','Retry','small')}</div>`:''}<div class="page">${pageContent()}</div></div></main></div>`;document.querySelector('[data-action=theme]')?.setAttribute('aria-label','Toggle dark mode');document.querySelector('[data-action=refresh]')?.setAttribute('aria-label','Refresh invoices');const search=$('#search');if(search)search.addEventListener('input',e=>{state.search=e.target.value;renderTable()});const filter=$('#filter');if(filter)filter.addEventListener('change',e=>{state.filter=e.target.value;renderTable()});const settingsForm=$('#settings-form');if(settingsForm)settingsForm.addEventListener('submit',saveSettings);animateCounters();}
function intro(title,sub,action=''){return `<div class="page-intro"><div><p class="eyebrow">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</p><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function pageContent(){if(state.loading)return intro('Opening your workspace…','Fetching invoices, payments, and activity.')+'<div class="stats"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><div class="skeleton skeleton-wide"></div>';switch(state.page){case'Overview':return overview();case'Invoices':return intro('Invoice ledger','Every balance, due date, and next step in one place.',button('new',icon('plus')+' New invoice','primary'))+invoicePanel(false);case'Conversations':return conversations();case'Payments':return paymentsPage();case'Connections':return connections();case'Onboarding':return onboarding();default:return settings()}}
function animatedMoney(value,currency='INR'){return `<strong class="metric-value" data-counter="${value}" data-currency="${escape(currency)}">${money(value,currency)}</strong>`}
function animateCounters(){if(document.documentElement.classList.contains('reduce-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('[data-counter]').forEach(el=>{const end=Number(el.dataset.counter),currency=el.dataset.currency||'INR',started=performance.now(),duration=650;const tick=now=>{const progress=Math.min((now-started)/duration,1),ease=1-Math.pow(1-progress,3);el.textContent=money(Math.round(end*ease),currency);if(progress<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)})}
function agingChart(open){const groups=[['Current',x=>status(x)==='Open'||status(x)==='Due today'],['1–7d',x=>status(x)==='Overdue'&&daysLate(x)<=7],['8–30d',x=>status(x)==='Overdue'&&daysLate(x)>7&&daysLate(x)<=30],['30d+',x=>status(x)==='Overdue'&&daysLate(x)>30]];const values=groups.map(([label,test])=>({label,value:open.filter(test).reduce((sum,x)=>sum+remaining(x),0)})),max=Math.max(...values.map(x=>x.value),1);return `<section class="panel aging-panel"><div class="panel-head"><div><h2>Receivables ageing</h2><p>Outstanding balance by age</p></div><span class="live-label"><i></i> Live</span></div><div class="aging-chart" role="img" aria-label="Outstanding invoice ageing chart">${values.map(({label,value})=>{const height=Math.max(1,Math.ceil(value/max*10));return `<button class="age-column" data-action="age-filter" data-filter="${label}" aria-label="${label}: ${money(value)}"><span class="age-value">${money(value)}</span><span class="age-track"><i class="height-${height}"></i></span><span>${label}</span></button>`}).join('')}</div></section>`}
function daysLate(x){if(!x.due_date)return 0;return Math.max(0,Math.floor((new Date()-new Date(x.due_date+'T12:00:00'))/86400000))}
function activityFeed(){const payments=state.payments.slice(0,4).map(p=>({type:'Payment recorded',copy:money(p.amount_minor),client:state.invoices.find(x=>x.id===p.invoice_id)?.client||'Invoice',date:p.created_at,icon:'check'}));const drafts=state.invoices.filter(x=>remaining(x)>0).slice(0,4).map(x=>({type:x.followup_state==='approved'?'Reminder approved':'Invoice monitored',copy:x.number,client:x.client,date:x.updated_at||x.created_at,icon:x.followup_state==='approved'?'chat':'invoice'}));return [...payments,...drafts].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,5).map((event,index)=>`<div class="activity-item activity-delay-${index}"><span class="event-icon">${icon(event.icon)}</span><div><p><strong>${escape(event.type)}</strong> · ${escape(event.copy)}</p><small>${escape(event.client)} · ${new Date(event.date).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</small></div></div>`).join('')||'<p class="muted">Activity will appear as invoices move forward.</p>'}
function overview(){const t=totals(state.invoices),open=state.invoices.filter(x=>remaining(x)>0),late=open.filter(x=>status(x)==='Overdue');return intro(`Good morning, ${escape(state.profile.fullName.split(' ')[0])}.`,'A calm view of what is owed, moving, and settled.',button('new',icon('plus')+' New invoice','primary'))+`<div class="stats"><article class="stat dark"><div class="stat-top">Outstanding ${icon('wallet')}</div>${animatedMoney(t.outstanding)}<small>${open.length} open invoice${open.length===1?'':'s'}</small><div class="mini-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></article><article class="stat"><div class="stat-top">Overdue ${icon('clock')}</div>${animatedMoney(t.overdue)}<small>${late.length} invoice${late.length===1?'':'s'} needs attention</small></article><article class="stat"><div class="stat-top">Collected ${icon('check')}</div>${animatedMoney(t.collected)}<small>Payments recorded to date</small></article></div><div class="insight-grid">${agingChart(open)}<section class="panel activity-panel"><div class="panel-head"><div><h2>Activity</h2><p>Latest workspace events</p></div>${button('refresh',icon('refresh'),'ghost square')}</div><div class="panel-body activity">${activityFeed()}</div></section></div><div class="dashboard-grid">${invoicePanel(true)}<aside class="dashboard-aside"><div class="stack"><section class="attention"><div class="row between"><div class="eyebrow">Agent status</div><span class="pulse-dot" aria-label="Active"></span></div><h2>${open.length} invoice${open.length===1?'':'s'} in view</h2><p>${open.length?'Drafts are ready for review. You stay in control before any message leaves.':'Add an invoice to begin a considerate follow-up flow.'}</p>${button('conversations','Review conversations '+icon('arrow'),'small')}</section><section class="panel quiet-control"><div class="panel-body"><span class="control-icon">${icon('shield')}</span><div><h3>Control stays with you</h3><p class="muted">Outbound delivery remains off until a provider is connected.</p></div></div></section></div></aside></div>`}
function filtered(overview=false){return state.invoices.filter(x=>(!overview||remaining(x)>0)&&(`${x.client} ${x.number} ${x.email}`.toLowerCase().includes(state.search.toLowerCase()))&&(state.filter==='All'||status(x)===state.filter)).sort((a,b)=>(a.due_date||'9999-12-31').localeCompare(b.due_date||'9999-12-31'))}
function invoicePanel(overview){return `<section class="panel"><div class="panel-head"><div><h2>${overview?'Next on your list':'Invoice ledger'}</h2><p>${overview?'Open invoices, ordered by due date.':'Select an invoice to view, edit, or record a payment.'}</p></div>${button('export',icon('download')+' Export','small')}</div><div class="search-row"><label class="search">${icon('search')}<input id="search" aria-label="Search invoices" placeholder="Search client or invoice…" value="${escape(state.search)}"></label><select id="filter" class="filter" aria-label="Filter invoice status">${['All','Open','Overdue','Due today','Paid'].filter(s=>!overview||s!=='Paid').map(s=>`<option ${state.filter===s?'selected':''}>${s}</option>`).join('')}</select></div><div id="invoice-table">${tableContent(overview)}</div></section>`}
function renderTable(){const el=$('#invoice-table');if(el)el.innerHTML=tableContent(state.page==='Overview')}
function tableContent(overview){const rows=filtered(overview);if(!rows.length)return `<div class="empty">${icon('invoice')}<h3>${state.search||state.filter!=='All'?'No matching invoices':overview&&state.invoices.length?'All caught up.':'Your first invoice starts here.'}</h3><p>${state.search||state.filter!=='All'?'Try another search or status.':'Add an invoice to track its balance and prepare a follow-up.'}</p>${button('new','Add invoice '+icon('plus'),'primary')}</div>`;return `<div class="table-wrap"><table><thead><tr><th>Client / invoice</th><th>Due date</th><th>Status</th><th class="num">Balance</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="invoice-open" data-action="detail" data-id="${x.id}"><strong>${escape(x.client)}</strong><small>${escape(x.number)}</small></button></td><td>${day(x.due_date)}</td><td>${tag(status(x))}</td><td class="num"><strong>${money(remaining(x),x.currency)}</strong>${x.paid_minor?`<small>${money(x.paid_minor,x.currency)} paid</small>`:''}</td><td>${button('detail',icon('arrow'),'ghost square',x.id)}</td></tr>`).join('')}</tbody></table></div><div class="panel-foot">${rows.length} invoice${rows.length===1?'':'s'} · Currency shown per invoice</div>`}
function reminder(x){return x.reminder_text||`Hi ${x.client},\n\nA quick reminder about invoice ${x.number} for ${money(remaining(x),x.currency)}, due on ${day(x.due_date)}. Please let us know when we can expect payment, or if there’s anything you need from us.\n\nIf you’ve already paid, please share the payment reference so we can update our records. Thank you!`}
function conversations(){const rows=state.invoices.filter(x=>remaining(x)>0),selected=rows.find(x=>x.id===state.conversationId)||rows[0];if(selected)state.conversationId=selected.id;return intro('Conversations','Review every draft before it becomes a customer touchpoint.')+`<div class="notice conversation-notice"><span class="pulse-dot"></span><div><strong>Review mode</strong><p>Approvals are saved, but nothing is sent until a messaging provider is connected.</p></div></div>${rows.length?`<div class="conversation-shell"><aside class="conversation-list" aria-label="Invoice conversations">${rows.map(x=>`<button data-action="select-conversation" data-id="${x.id}" class="conversation-row ${x.id===selected?.id?'active':''}" ${x.id===selected?.id?'aria-current="true"':''}><span class="avatar">${escape(x.client.slice(0,2).toUpperCase())}</span><span><strong>${escape(x.client)}</strong><small>${escape(x.number)} · ${money(remaining(x),x.currency)}</small></span>${tag(x.followup_state)}</button>`).join('')}</aside><section class="conversation-thread" aria-label="Conversation with ${escape(selected.client)}"><header><div class="row"><span class="avatar">${escape(selected.client.slice(0,2).toUpperCase())}</span><div><h2>${escape(selected.client)}</h2><small>${escape(selected.number)} · ${day(selected.due_date)}</small></div></div>${tag(selected.followup_state)}</header><div class="thread-body"><div class="thread-date">Draft preview</div><div class="message-bubble"><p>${escape(reminder(selected)).replaceAll('\n','<br>')}</p><small>Prepared by cetld · Not sent</small></div></div><footer><div class="draft-state"><span class="pulse-dot"></span> Human review required</div><div class="actions">${button('draft',icon('edit')+' Edit draft','small',selected.id)}${button('copy','Copy','small',selected.id)}${canApprove(selected)?button('approve',icon('check')+' Approve','small primary',selected.id):''}${selected.followup_state==='approved'?button('pause',icon('pause')+' Pause','small',selected.id):''}${selected.followup_state!=='cancelled'?button('cancel','Cancel','small ghost',selected.id):''}</div></footer></section></div>`:`<section class="panel empty">${icon('chat')}<h3>No conversations need review.</h3><p>Open invoices will appear here with an editable reminder draft.</p>${button('new','Add an invoice','primary')}</section>`}`}
function paymentsPage(){return intro('Every payment, accounted for.','Record payments you’ve received. Cetld does not move money.')+`<section class="panel"><div class="panel-head"><h2>Payment history</h2>${button('invoices','Find an invoice '+icon('arrow'),'small')}</div>${state.payments.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Recorded</th><th>Reference</th><th class="num">Amount</th></tr></thead><tbody>${state.payments.map(p=>{const x=state.invoices.find(x=>x.id===p.invoice_id);return `<tr><td>${escape(x?.client||'Invoice')}<small>${escape(x?.number)}</small></td><td>${new Date(p.created_at).toLocaleDateString('en-IN')}</td><td>${escape(p.reference||'—')}</td><td class="num">${money(p.amount_minor,x?.currency)}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">${icon('wallet')}<h3>A clean ledger.</h3><p>Open an invoice and choose “Record payment” when money arrives.</p>${button('invoices','View invoices','primary')}</div>`}</section>`}
function connections(){return intro('Connected, with intention.','A clear picture of what’s active and what still needs setup.')+`<section class="panel">${[['S','Supabase','Authentication and private invoice storage.',state.demo?'Demo mode':'Connected'],['Z','Zoho Books','Invoice import and accounting sync are not configured.','Not connected'],['W','WhatsApp & voice','No delivery provider is configured. Reminders remain drafts.','Not connected'],['R','Resend','Custom transactional email delivery is not configured.','Not connected'],['S','Sentry','Application error monitoring is not configured.','Not connected']].map(([i,n,d,s])=>`<div class="integration"><span class="integration-icon">${i}</span><div><h3>${n}</h3><p>${d}</p></div>${tag(s)}</div>`).join('')}</section><div class="quiet-strip">${icon('shield')}Connecting an account in ChatGPT does not automatically configure this app’s runtime integration.</div>`}
function onboarding(){const hasInvoice=state.invoices.length>0;return `<div class="onboarding"><div class="onboarding-copy"><span class="eyebrow">Workspace setup</span><h1>Three calm steps to a clearer ledger.</h1><p>Set up the essentials now. Messaging stays off until you explicitly connect and approve it.</p><ol class="setup-steps"><li class="complete"><span>${icon('check')}</span><div><strong>Workspace secured</strong><small>Your account and private records are ready.</small></div></li><li class="${hasInvoice?'complete':'current'}"><span>${hasInvoice?icon('check'):'2'}</span><div><strong>Add your first invoice</strong><small>Upload a PDF or image, or enter it manually.</small></div></li><li class="current"><span>3</span><div><strong>Review a conversation</strong><small>Edit and approve the draft before connecting delivery.</small></div></li></ol><div class="row">${button(hasInvoice?'conversations':'new',hasInvoice?'Review conversation '+icon('arrow'):'Add invoice '+icon('plus'),'primary')}${button('navigate','Back to overview','ghost')}</div></div><div class="onboarding-preview"><div class="preview-top"><span class="pulse-dot"></span><span>Quiet follow-up flow</span></div><div class="preview-step"><b>01</b><span>Invoice enters your ledger</span>${icon('check')}</div><div class="preview-line"></div><div class="preview-step"><b>02</b><span>cetld prepares a draft</span>${icon('chat')}</div><div class="preview-line"></div><div class="preview-step muted-step"><b>03</b><span>You review before delivery</span>${icon('shield')}</div></div></div>`}
function settings(){const name=state.profile.fullName,business=state.profile.businessName||'';return intro('Settings','Shape the workspace without adding noise.')+`<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections"><a href="#profile">Profile</a><a href="#preferences">Preferences</a><a href="#account">Account</a>${button('onboarding','Setup guide '+icon('arrow'),'ghost wide')}</nav><div class="settings-content"><section class="panel" id="profile"><div class="panel-head"><div><h2>Workspace profile</h2><p>Saved securely to this workspace.</p></div><span class="avatar">${escape(state.profile.initials)}</span></div><form class="panel-body settings-fields" id="settings-form"><label class="field">Full name<input name="full_name" value="${escape(name)}" required maxlength="160"></label><label class="field">Business name<input name="business_name" value="${escape(business)}" required maxlength="200"></label><label class="field">Default currency<input name="default_currency" value="${escape(state.settings?.default_currency||'INR')}" required maxlength="3" pattern="[A-Za-z]{3}"></label><label class="field">Timezone<input name="default_timezone" value="${escape(state.settings?.default_timezone||'Asia/Kolkata')}" required maxlength="80"></label><div class="error hidden" data-error role="alert"></div><button class="btn primary" type="submit">Save settings</button></form></section><section class="panel" id="preferences"><div class="panel-head"><div><h2>Preferences</h2><p>Saved on this device.</p></div></div><div class="panel-body"><label class="setting-row"><div><h3>Dark mode</h3><p>Use deep ink surfaces throughout the workspace.</p></div><input type="checkbox" class="toggle" data-setting="theme" aria-label="Dark mode" ${document.documentElement.classList.contains('dark')?'checked':''}></label><label class="setting-row"><div><h3>Reduce motion</h3><p>Disable counters, entrances, pulses, and transitions.</p></div><input type="checkbox" class="toggle" data-setting="motion" aria-label="Reduce motion" ${document.documentElement.classList.contains('reduce-motion')?'checked':''}></label></div></section><section class="panel" id="account"><div class="panel-head"><div><h2>Account</h2><p>${escape(state.user.email)}</p></div>${tag(state.demo?'Demo':'Private')}</div><div class="panel-body">${button('logout',icon('logout')+(state.demo?' Exit demo':' Sign out'),'wide')}<small>${state.demo?'Demo changes are discarded when you leave.':'Saved invoices remain private to your workspace when you sign out.'}</small></div></section></div></div>`}
async function saveSettings(e){e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type=submit]');submit.disabled=true;try{if(state.demo)throw Error('Settings persistence requires a signed-in account.');const values=new FormData(form),fullName=String(values.get('full_name')||'').trim(),businessName=String(values.get('business_name')||'').trim(),currency=String(values.get('default_currency')||'').trim().toUpperCase(),timezone=String(values.get('default_timezone')||'').trim();if(!fullName||!businessName||!/^[A-Z]{3}$/.test(currency)||!timezone)throw Error('Complete all settings with a valid three-letter currency.');const [profileResult,settingsResult,workspaceResult]=await Promise.all([db.from('profiles').upsert({user_id:state.user.id,full_name:fullName}).select().single(),db.from('workspace_settings').update({business_name:businessName,default_currency:currency,default_timezone:timezone}).eq('workspace_id',state.workspace.id).select().single(),db.from('workspaces').update({name:businessName}).eq('id',state.workspace.id).select().single()]);for(const result of [profileResult,settingsResult,workspaceResult])if(result.error)throw result.error;state.settings=settingsResult.data;state.workspace=workspaceResult.data;state.profile={...state.profile,fullName,businessName,secondaryLabel:businessName,initials:profileFromUser({email:state.user.email,user_metadata:{full_name:fullName}}).initials};render();toast('Settings saved')}catch(err){showError(form,err)}finally{submit.disabled=false}}
function openDialog(title,body,footer='',variant=''){const d=$('#dialog');d.className=variant;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="btn ghost square" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer}`;if(!d.open)d.showModal()}
function detail(id){const x=state.invoices.find(x=>x.id===id);if(!x)return;openDialog(escape(x.number),`<div class="detail-hero"><div><p class="eyebrow">Outstanding balance</p><p class="detail-amount">${money(remaining(x),x.currency)}</p></div>${tag(status(x))}</div><div class="dialog-body detail-body"><div class="client-card"><span class="avatar">${escape(x.client.slice(0,2).toUpperCase())}</span><div><h3>${escape(x.client)}</h3><p class="muted">${escape(x.email||'No email provided')}</p></div></div><dl class="detail-facts"><div><dt>Invoice total</dt><dd>${money(x.amount_minor,x.currency)}</dd></div><div><dt>Payments recorded</dt><dd>${money(x.paid_minor,x.currency)}</dd></div><div><dt>Invoice date</dt><dd>${day(x.invoice_date)}</dd></div><div><dt>Due date</dt><dd>${day(x.due_date)}</dd></div><div><dt>Follow-up</dt><dd>${tag(x.followup_state)}</dd></div><div><dt>Bookkeeping</dt><dd>${tag(x.bookkeeping_sync_status||'not_configured')}</dd></div></dl>${x.notes?`<div class="detail-note"><span class="eyebrow">Notes</span><p>${escape(x.notes)}</p></div>`:''}</div><div class="drawer-actions">${button('edit',icon('edit')+' Edit','',id)}${remaining(x)>0?button('draft','Review draft','',id):''}${remaining(x)>0?button('payment','Record payment','primary',id):''}</div>`, '', 'detail-drawer')}
function setIngestionState(form,text,kind=''){const el=form.querySelector('[data-ingestion-state]');if(!el)return;el.textContent=text;el.dataset.kind=kind;el.classList.remove('hidden')}
async function ingestFile(form,file){if(state.demo)throw Error('Sign in to upload invoice files. Demo mode supports manual entry only.');if(file.size>10*1024*1024)throw Error('Invoice files must be 10 MB or smaller.');const allowed=['application/pdf','image/jpeg','image/png','image/webp'];if(!allowed.includes(file.type))throw Error('Upload a PDF, JPG, PNG, or WEBP invoice.');state.pendingFile=file;setIngestionState(form,'File ready · save the invoice to upload securely','ready');return {file_name:file.name}}
function invoiceForm(id){state.pendingFile=null;const x=state.invoices.find(x=>x.id===id);openDialog(x?'Edit invoice':'New invoice',`<form id="invoice-form"><div class="dialog-body"><div class="ingestion-panel"><label class="field">Upload invoice image or PDF<input name="source_file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></label><p>The original is uploaded to private workspace storage when you save.</p><div class="ingestion-state hidden" data-ingestion-state aria-live="polite"></div></div><div class="two-cols"><label class="field">Invoice number<input name="number" value="${escape(x?.number||'')}" maxlength="60"></label><label class="field">Due date<input name="due_date" type="date" value="${x?.due_date||''}"></label></div><label class="field">Buyer / debtor<input name="client" value="${escape(x?.client)}" maxlength="160" required></label><div class="two-cols"><label class="field">Invoice total<input name="amount" inputmode="decimal" value="${x?x.amount_minor/100:''}" placeholder="0.00" required></label><label class="field">Currency<input name="currency" value="${escape(x?.currency||'INR')}" maxlength="3" pattern="[A-Za-z]{3}" required></label></div><div class="two-cols"><label class="field">Invoice date<input name="invoice_date" type="date" value="${x?.invoice_date||''}"></label><label class="field">Tax (optional)<input name="tax" inputmode="decimal" value="${x?.tax_minor==null?'':x.tax_minor/100}" placeholder="0.00"></label></div><div class="two-cols"><label class="field">Client email (optional)<input type="email" name="email" value="${escape(x?.email)}" maxlength="254"></label><label class="field">Debtor phone (optional)<input name="debtor_phone" value="${escape(x?.debtor_phone)}" maxlength="80"></label></div><input type="hidden" name="seller_name" value="${escape(x?.seller_name)}"><input type="hidden" name="buyer_name" value="${escape(x?.buyer_name||x?.client)}"><input type="hidden" name="payment_information" value="${escape(x?.payment_information)}"><label class="field">Notes (optional)<textarea name="notes" maxlength="4000">${escape(x?.notes)}</textarea></label><div class="error hidden" data-error role="alert"></div></div><div class="dialog-foot">${button('close','Cancel')}<button class="btn primary" type="submit">Save invoice</button></div></form>`);const form=$('#invoice-form');form.addEventListener('change',e=>{if(e.target.name==='source_file'&&e.target.files[0]){const file=e.target.files[0];ingestFile(form,file).catch(err=>{setIngestionState(form,err.message,'failed');showError(form,err)})}});form.addEventListener('submit',e=>saveInvoice(e,x))}
async function saveInvoice(e,x){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('[type=submit]');btn.disabled=true;try{const f=new FormData(form),currency=String(f.get('currency')||'').trim().toUpperCase(),rawAmount=String(f.get('amount')||'').trim(),rawTax=String(f.get('tax')||'').trim();if(!/^[A-Z]{3}$/.test(currency))throw Error('Currency must be a three-letter code such as INR or USD.');const patch={number:String(f.get('number')||'').trim(),client:String(f.get('client')||'').trim(),email:String(f.get('email')||'').trim(),amount_minor:cents(rawAmount),currency,invoice_date:String(f.get('invoice_date')||'')||localDate(),tax_minor:rawTax?cents(rawTax):null,due_date:String(f.get('due_date')||'')||null,notes:String(f.get('notes')||'').trim(),seller_name:String(f.get('seller_name')||'').trim(),buyer_name:String(f.get('buyer_name')||'').trim()||String(f.get('client')||'').trim(),debtor_phone:String(f.get('debtor_phone')||'').trim(),payment_information:String(f.get('payment_information')||'').trim(),line_items:JSON.parse(form.dataset.lineItems||'[]'),extraction_status:state.pendingFile?'uploaded':'manual',bookkeeping_sync_status:'not_configured'};if(!patch.number||!patch.client)throw Error('Invoice number and buyer/debtor are required.');if(x&&patch.amount_minor<x.paid_minor)throw Error('Total cannot be less than payments already recorded.');if(state.invoices.some(y=>y.id!==x?.id&&y.number===patch.number))throw Error('This invoice number already exists.');if(state.demo){if(x)Object.assign(x,patch,{updated_at:new Date().toISOString()});else state.invoices.unshift({...patch,id:crypto.randomUUID(),paid_minor:0,followup_state:'draft',reminder_text:'',created_at:new Date().toISOString(),updated_at:new Date().toISOString()})}else{let customer=state.customers.find(customer=>customer.id===x?.customer_id)||state.customers.find(customer=>patch.email&&customer.email?.toLowerCase()===patch.email.toLowerCase())||state.customers.find(customer=>customer.name.toLowerCase()===patch.client.toLowerCase());const customerPayload={workspace_id:state.workspace.id,name:patch.client,company_name:patch.client,email:patch.email||null,phone:patch.debtor_phone||null};if(customer){const result=await db.from('customers').update(customerPayload).eq('workspace_id',state.workspace.id).eq('id',customer.id).select().single();if(result.error)throw result.error;customer=result.data}else{const result=await db.from('customers').insert(customerPayload).select().single();if(result.error)throw result.error;customer=result.data;state.customers.push(customer)}const metadata={followup_state:x?.followup_state||'draft',reminder_text:x?.reminder_text||'',bookkeeping_sync_status:'not_configured',tax_minor:patch.tax_minor,seller_name:patch.seller_name,buyer_name:patch.buyer_name,debtor_phone:patch.debtor_phone,payment_information:patch.payment_information,line_items:patch.line_items,extraction_status:patch.extraction_status};const invoicePayload={workspace_id:state.workspace.id,customer_id:customer.id,invoice_number:patch.number,issue_date:patch.invoice_date,due_date:patch.due_date,currency,total_amount:patch.amount_minor/100,notes:patch.notes||null,metadata};const query=x?db.from('invoices').update(invoicePayload).eq('workspace_id',state.workspace.id).eq('id',x.id).eq('updated_at',x.updated_at):db.from('invoices').insert(invoicePayload);const result=await query.select().single();if(result.error)throw result.error;const invoice=result.data;if(state.pendingFile){const file=state.pendingFile,safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${state.workspace.id}/${invoice.id}/${crypto.randomUUID()}-${safeName}`;const upload=await db.storage.from('invoice-files').upload(path,file,{contentType:file.type,upsert:false});if(upload.error)throw upload.error;const fileRow=await db.from('invoice_files').insert({workspace_id:state.workspace.id,invoice_id:invoice.id,storage_path:path,file_name:file.name,mime_type:file.type,size_bytes:file.size});if(fileRow.error)throw fileRow.error;state.pendingFile=null}}$('#dialog').close();await loadData();toast('Invoice saved · bookkeeping sync is not configured')}catch(err){showError(form,err)}finally{btn.disabled=false}}
function paymentForm(id){const x=state.invoices.find(x=>x.id===id);if(!x||!remaining(x))return;openDialog('Record a payment',`<form id="payment-form"><div class="dialog-body"><p>${escape(x.client)} · ${escape(x.number)}</p><div class="notice">Recording money you’ve already received. Balance: ${money(remaining(x),x.currency)}.</div><label class="field">Amount received (${escape(x.currency||'INR')})<input name="amount" inputmode="decimal" value="${remaining(x)/100}" required></label><label class="field">Payment reference (optional)<input name="reference" placeholder="Bank transfer / UTR / receipt number" maxlength="250"></label><div class="error hidden" data-error role="alert"></div></div><div class="dialog-foot">${button('close','Cancel')}<button class="btn primary" type="submit">Record payment</button></div></form>`);$('#payment-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('[type=submit]');btn.disabled=true;try{const f=new FormData(form),amount=cents(f.get('amount')),next=payment(x,amount);if(state.demo){Object.assign(x,next);state.payments.unshift({id:crypto.randomUUID(),invoice_id:x.id,amount_minor:amount,reference:f.get('reference'),created_at:new Date().toISOString()})}else{const paymentResult=await db.from('payments').insert({workspace_id:state.workspace.id,invoice_id:x.id,amount:amount/100,reference:String(f.get('reference')||'').trim()||null});if(paymentResult.error)throw paymentResult.error;const metadata={...(x.metadata||{}),followup_state:next.followup_state};const invoiceResult=await db.from('invoices').update({amount_paid:next.paid_minor/100,status:next.paid_minor===x.amount_minor?'paid':x.status,metadata}).eq('workspace_id',state.workspace.id).eq('id',x.id);if(invoiceResult.error)throw invoiceResult.error}$('#dialog').close();await loadData();toast(remaining(state.invoices.find(i=>i.id===id))===0?'Payment recorded. Invoice settled; follow-up cancelled.':'Payment recorded')}catch(err){showError(form,err)}finally{btn.disabled=false}})}
function draftForm(id){const x=state.invoices.find(x=>x.id===id);if(!x)return;openDialog('Edit reminder draft',`<form id="draft-form"><div class="dialog-body"><p>${escape(x.client)} · ${escape(x.number)}</p><label class="field">Message<textarea name="message" rows="9" maxlength="4000" required>${escape(reminder(x))}</textarea></label><small>Saving an edit resets approval so you can review the new wording.</small><div class="error hidden" data-error role="alert"></div></div><div class="dialog-foot">${button('close','Cancel')}<button class="btn primary" type="submit">Save draft</button></div></form>`);$('#draft-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('[type=submit]');btn.disabled=true;try{const text=new FormData(form).get('message').trim();if(!text)throw Error('Write a message before saving.');await updateInvoice(x,{reminder_text:text,followup_state:'draft'});$('#dialog').close();render();toast('Draft saved for review')}catch(err){showError(form,err)}finally{btn.disabled=false}})}
async function updateInvoice(x,patch){if(state.demo){Object.assign(x,patch);return}const metadata={...(x.metadata||{}),followup_state:patch.followup_state??x.followup_state,reminder_text:patch.reminder_text??x.reminder_text};const {data,error}=await db.from('invoices').update({metadata}).eq('workspace_id',state.workspace.id).eq('id',x.id).eq('updated_at',x.updated_at).select().single();if(error)throw Error(error.code==='PGRST116'?'This invoice changed. Refresh and try again.':error.message);const mapped=invoiceFromRow(data,state.customers);state.invoices=state.invoices.map(y=>y.id===x.id?mapped:y)}
function exportInvoices(){const rows=[['Invoice','Client','Email','Due date','Total INR','Paid INR','Balance INR','Status'],...filtered(state.page==='Overview').map(x=>[x.number,x.client,x.email,x.due_date,x.amount_minor/100,x.paid_minor/100,remaining(x)/100,status(x)])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cetld-invoices-'+localDate()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Invoice export downloaded')}
async function logout(){if(!state.demo){const {error}=await db.auth.signOut({scope:'local'});if(error){toast(error.message);return}}++loadEpoch;state.user=null;state.profile=profileFromUser(null);state.workspace=null;state.settings=null;state.customers=[];state.pendingFile=null;state.demo=false;state.invoices=[];state.payments=[];state.authMode='login';state.search='';state.filter='All';state.error='';authError='';$('#dialog').close();authPage()}
document.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;try{if(action==='close')return $('#dialog').close();if(action.startsWith('auth-')){state.authMode=action.slice(5);authError='';return authPage()}if(action==='google')return await googleSignIn();if(action==='demo')return demo();if(action==='logout')return await logout();if(action==='menu'){document.querySelector('.sidebar')?.classList.toggle('open');document.querySelector('.nav-scrim')?.classList.toggle('open');return}if(action==='theme'){const dark=document.documentElement.classList.toggle('dark');pref('cetld.theme',dark?'dark':'light');return}if(action==='onboarding'){state.page='Onboarding';render();return}if(action==='overview'){state.page='Overview';render();return}if(action==='select-conversation'){state.conversationId=id;render();return}if(action==='age-filter'){state.page='Invoices';state.search='';state.filter=b.dataset.filter==='Current'?'Open':'Overdue';render();return}if(action==='navigate'||['invoices','conversations'].includes(action)){state.page=action==='navigate'?(b.dataset.page||'Overview'):action==='invoices'?'Invoices':'Conversations';state.search='';state.filter='All';render();return}if(action==='refresh')return await loadData();if(action==='new')return invoiceForm();if(action==='detail')return detail(id);if(action==='edit')return invoiceForm(id);if(action==='payment')return paymentForm(id);if(action==='draft')return draftForm(id);if(action==='export')return exportInvoices();const x=state.invoices.find(x=>x.id===id);if(!x)return;if(action==='copy'){await navigator.clipboard.writeText(reminder(x));toast('Draft copied');return}if(['approve','pause','cancel'].includes(action)){b.disabled=true;if(action==='approve'&&!canApprove(x))throw Error('Only an unpaid draft can be approved.');await updateInvoice(x,{followup_state:action==='approve'?'approved':action==='pause'?'paused':'cancelled'});render();toast(action==='approve'?'Approval saved. Delivery is not connected.':action==='pause'?'Follow-up paused':'Follow-up cancelled')}}catch(err){toast(err.message||'Something went wrong. Please try again.')}finally{b.disabled=false}});
document.addEventListener('change',e=>{if(e.target.dataset.setting==='theme'){document.documentElement.classList.toggle('dark',e.target.checked);pref('cetld.theme',e.target.checked?'dark':'light')}if(e.target.dataset.setting==='motion'){document.documentElement.classList.toggle('reduce-motion',e.target.checked);pref('cetld.motion',e.target.checked?'off':'on')}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
async function init(){authError='Connecting securely…';authPage();try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');db=createClient(config.url,config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});authError='';db.auth.onAuthStateChange((event,session)=>{if(event==='USER_UPDATED'&&session?.user&&!state.demo){state.user=session.user;state.profile=profileFromUser(session.user);render()}else if(event==='PASSWORD_RECOVERY'){state.recovery=true;state.authMode='recovery';state.user=session?.user;state.profile=profileFromUser(session?.user);authPage()}else if(event==='SIGNED_OUT'&&!state.demo){++loadEpoch;state.user=null;state.profile=profileFromUser(null);state.workspace=null;state.settings=null;state.customers=[];state.invoices=[];state.payments=[];$('#dialog').close();authPage()}});const {data,error}=await db.auth.getSession();if(error)throw error;if(state.recovery)return;if(data.session){const {data:userData,error:userError}=await db.auth.getUser();if(userError)throw userError;await enterAccount(userData.user)}else if(!state.demo)authPage()}catch(err){authError='Secure sign-in could not load. Check your connection and reload. The demo is still available.';if(!state.demo)authPage()}}
init();
